TIMEOUT = 5


def exact(sock, length):
    data = bytearray()
    while len(data) < length:
        chunk = sock.recv(length - len(data))
        if not chunk:
            raise ConnectionError('DNS upstream closed connection')
        data.extend(chunk)
    return bytes(data)


